on conflict (key) do update set version = excluded.version, title = excluded.title, description = excluded.description,
  contents = excluded.contents, active = excluded.active, content = excluded.content;

-- ── 2. The community that exists ───────────────────────────────────────────────────────────────────────────────────────
-- Every demo community still on an older pack: aligned in place (nothing to do when it already is) and marked for the next reload with an
-- audit entry that is not a job's (see the header). The loaded version is left as it is: the reload itself writes the new one.
do $$
declare c record; v_pack int := (select p.version from app.demo_packs p where p.key = 'demo_faith_jain_v1');
begin
  for c in
    select ce.id
      from app.centers ce left join app.center_demo_state s on s.center_id = ce.id
     where app.is_demo_center(ce.id) and ce.environment = 'sandbox' and ce.rules ->> 'demo_pack' = 'demo_faith_jain_v1'
       and s.version is distinct from v_pack
     order by ce.created_at, ce.id
  loop
    perform app.set_audit_context('The faith demo pack changed: the community member finds a full app (history, giving choices, calendar, guide, Learning Center) (migration 0878)');
    perform app.demo_align_center(c.id);
    perform app.log_audit(c.id, 'demo.pack_updated', 'center_demo_state', c.id::text, null,
      jsonb_build_object('pack', 'demo_faith_jain_v1', 'version', v_pack),
      'The pack changed (migration 0878): the community is reloaded at the next nightly check, or when Start over is pressed');
  end loop;
end $$;

